-- =============================================================================
-- V013  workflow — state machines per service, their history, and tasks
-- =============================================================================
-- One engine for every per-service status flow (legacy OrdersFlow plus the
-- ordersStatus.json vocabulary) and company-wide tasks (legacy Tasks,
-- TaskHistory).
--
-- v3 changes (V3_DESIGN.md S workflow; review F05; D4 rule 9):
--   * every table carries tenant_id (RLS, C2);
--   * workflow_definitions are keyed by ALL legacy dimensions — order type,
--     isDigital AND serviceID (v2 collapsed 18 source dimensions to 16) —
--     plus service_family;
--   * workflow_states: sla_minutes replaces sla_hours / sla_business_hours;
--   * new legacy_status_codes: (definition, legacy status id) -> state;
--   * states referenced inside a definition must belong to that definition
--     (composite FKs on (definition_id, state id));
--   * workflow_history and task_status_history are append-only and gain
--     actor_role_id; new append-only task_due_date_changes (reason required).
-- Every FK to another file is in migrations/fk/workflow.sql (V090).
-- The transition validator and SLA functions are V100, not here.
-- =============================================================================

-- ---------------------------------------------------------------- workflow_definitions
CREATE TABLE workflow.workflow_definitions (
    id                     bigint GENERATED BY DEFAULT AS IDENTITY,
    tenant_id              bigint       NOT NULL DEFAULT core.fn_current_tenant(),
    code                   core.entity_code NOT NULL,
    name                   varchar(150) NOT NULL,
    entity_type            varchar(50)  NOT NULL,
    service_family         varchar(40),
    legacy_order_type_id   integer,
    legacy_is_digital      boolean,
    legacy_service_id      integer,
    description            text,
    version                smallint     NOT NULL DEFAULT 1,
    is_active              boolean      NOT NULL DEFAULT true,
    legacy_id              bigint,
    legacy_source          varchar(64),
    legacy_key             varchar(200),
    created_at             timestamptz  NOT NULL DEFAULT now(),
    updated_at             timestamptz  NOT NULL DEFAULT now(),
    created_by_user_id     bigint,
    updated_by_user_id     bigint,
    CONSTRAINT pk_workflow_definitions PRIMARY KEY (id),
    CONSTRAINT uq_workflow_definitions__tenant_id__code__version UNIQUE (tenant_id, code, version),
    CONSTRAINT ck_workflow_definitions__entity_type CHECK (entity_type IN ('order', 'order_item', 'task', 'voucher', 'shipment', 'production_job', 'qc_inspection')),
    CONSTRAINT ck_workflow_definitions__service_family CHECK (service_family IS NULL OR service_family IN (
        'laser_scan', 'intraoral_scan', 'conversion', 'treatment_plan', 'treatment_plan_ai', 'surgical_guide',
        'report', 'restoration', 'gfmr', 'fmp', 'ismile', 'ortho', 'software', 'training', 'voucher',
        'misc', 'other_services', 'appliance', 'simulation', 'elite_scanner')),
    CONSTRAINT ck_workflow_definitions__legacy_dims_coherent CHECK (
        legacy_order_type_id IS NOT NULL OR (legacy_is_digital IS NULL AND legacy_service_id IS NULL)),
    CONSTRAINT ck_workflow_definitions__legacy_dims_complete CHECK (
        legacy_order_type_id IS NULL OR legacy_is_digital IS NOT NULL),
    CONSTRAINT ck_workflow_definitions__version_positive CHECK (version >= 1)
);
CREATE UNIQUE INDEX uq_workflow_definitions__legacy ON workflow.workflow_definitions (legacy_source, legacy_id, COALESCE(legacy_key, ''))
    WHERE legacy_id IS NOT NULL OR legacy_key IS NOT NULL;
CREATE UNIQUE INDEX uq_workflow_definitions__legacy_dims ON workflow.workflow_definitions
    (tenant_id, legacy_order_type_id, legacy_is_digital, legacy_service_id, version) NULLS NOT DISTINCT
    WHERE legacy_order_type_id IS NOT NULL;

COMMENT ON TABLE workflow.workflow_definitions IS 'A state machine: the ordered set of states and allowed transitions that one kind of entity (usually an order item of one service family) moves through. Legacy OrdersFlow keyed its flows on (OrderType, isDigital, serviceID) — 18 distinct combinations; v3 keeps one definition per combination (review F05; v2 ignored serviceID and collapsed them to 16). Versioned by (code, version); a definition in use is deactivated, not deleted. Seeded by ETL stage 60 / V2nn seeds.';
COMMENT ON COLUMN workflow.workflow_definitions.id IS 'Surrogate key of the definition; system-generated.';
COMMENT ON COLUMN workflow.workflow_definitions.tenant_id IS 'Owning tenant (core.tenants); filtered by RLS.';
COMMENT ON COLUMN workflow.workflow_definitions.code IS 'Stable code of the flow, unique per tenant and version, e.g. order_flow_3_digital_s12; referenced by catalog.sellable_items.workflow_code.';
COMMENT ON COLUMN workflow.workflow_definitions.name IS 'Display name of the flow for staff, e.g. "Surgical Guide (digital)".';
COMMENT ON COLUMN workflow.workflow_definitions.entity_type IS 'What the flow drives: ''order'' = a whole order; ''order_item'' = one service line (all OrdersFlow flows); ''task'' = a workflow.tasks row; ''voucher'' = a voucher; ''shipment'' = a shipment; ''production_job'' = a production job; ''qc_inspection'' = a quality inspection.';
COMMENT ON COLUMN workflow.workflow_definitions.service_family IS 'Service family the flow serves (glossary; ordersStatus.json group names normalised): ''laser_scan'', ''intraoral_scan'', ''conversion'', ''treatment_plan'', ''treatment_plan_ai'', ''surgical_guide'', ''report'', ''restoration'' (temporary/final), ''gfmr'', ''fmp'' (FMP/GFMP), ''ismile'', ''ortho'', ''software'', ''training'', ''voucher'', ''misc'', ''other_services'', ''appliance'', ''simulation'', ''elite_scanner''. A new family needs a migration. NULL = not an order-item flow (task, voucher, shipment flows) or family not yet assigned.';
COMMENT ON COLUMN workflow.workflow_definitions.legacy_order_type_id IS 'Legacy OrdersFlow.OrderType (OrderTypes.id) this flow was built from. NULL = flow defined in threeddx3, not migrated from OrdersFlow.';
COMMENT ON COLUMN workflow.workflow_definitions.legacy_is_digital IS 'Legacy OrdersFlow.isDigital (1 = digital delivery flow, 0 = physical); required when legacy_order_type_id is set. NULL = not migrated from OrdersFlow.';
COMMENT ON COLUMN workflow.workflow_definitions.legacy_service_id IS 'Legacy OrdersFlow.serviceID (Services.id) — the 18th dimension v2 dropped (review F05). NULL = the source flow applies to every service of the order type (OrdersFlow.serviceID NULL), or not migrated.';
COMMENT ON COLUMN workflow.workflow_definitions.description IS 'What the flow covers and when it is used; user input. NULL = no description.';
COMMENT ON COLUMN workflow.workflow_definitions.version IS 'Version number of the flow under the same code, starting at 1; a changed flow is a new version so running instances keep their definition.';
COMMENT ON COLUMN workflow.workflow_definitions.is_active IS 'False = no new instances start on this definition; existing instances continue.';
COMMENT ON COLUMN workflow.workflow_definitions.legacy_id IS 'Source row id when one identifies the flow. NULL = flows are identified by legacy_key / the legacy dimension columns, or created in threeddx3.';
COMMENT ON COLUMN workflow.workflow_definitions.legacy_source IS 'Source: ''OrdersFlow'', ''ec2:ordersStatus.json'' or ''derived''. NULL = created in threeddx3.';
COMMENT ON COLUMN workflow.workflow_definitions.legacy_key IS 'Composite source key ''<OrderType>|<isDigital>|<serviceID or null>'' for OrdersFlow flows. NULL = not migrated.';
COMMENT ON COLUMN workflow.workflow_definitions.created_at IS 'UTC instant the row was created; system-generated. [AUDIT]';
COMMENT ON COLUMN workflow.workflow_definitions.updated_at IS 'UTC instant of the last change; maintained by trg_workflow_definitions__touch_updated_at. [AUDIT]';
COMMENT ON COLUMN workflow.workflow_definitions.created_by_user_id IS 'Staff user who created the definition; no FK by design. NULL = system or migration. [AUDIT]';
COMMENT ON COLUMN workflow.workflow_definitions.updated_by_user_id IS 'Staff user who last changed the definition; no FK by design. NULL = system or never changed. [AUDIT]';
COMMENT ON CONSTRAINT pk_workflow_definitions ON workflow.workflow_definitions IS 'One row per definition version.';
COMMENT ON CONSTRAINT uq_workflow_definitions__tenant_id__code__version ON workflow.workflow_definitions IS 'A flow code has one row per version within a tenant; the ETL upserts on (tenant_id, code, version).';
COMMENT ON CONSTRAINT ck_workflow_definitions__entity_type ON workflow.workflow_definitions IS 'A flow drives one of the seven entity kinds the engine knows.';
COMMENT ON CONSTRAINT ck_workflow_definitions__service_family ON workflow.workflow_definitions IS 'The service family, when given, is one of the documented families.';
COMMENT ON CONSTRAINT ck_workflow_definitions__legacy_dims_coherent ON workflow.workflow_definitions IS 'isDigital and serviceID only have meaning together with the legacy order type they qualify.';
COMMENT ON CONSTRAINT ck_workflow_definitions__legacy_dims_complete ON workflow.workflow_definitions IS 'A flow migrated from OrdersFlow always records its isDigital dimension (part of the source primary key).';
COMMENT ON CONSTRAINT ck_workflow_definitions__version_positive ON workflow.workflow_definitions IS 'Versions start at 1.';
COMMENT ON INDEX workflow.uq_workflow_definitions__legacy IS 'Every migrated definition is traceable and cannot be loaded twice.';
COMMENT ON INDEX workflow.uq_workflow_definitions__legacy_dims IS 'One definition (per version) per legacy (OrderType, isDigital, serviceID) combination, NULL serviceID counted as a value: the 18 source dimensions cannot collapse again (review F05). Also serves "which flow does this legacy item use".';
CREATE TRIGGER trg_workflow_definitions__touch_updated_at BEFORE UPDATE ON workflow.workflow_definitions
    FOR EACH ROW EXECUTE FUNCTION core.fn_touch_updated_at();
COMMENT ON TRIGGER trg_workflow_definitions__touch_updated_at ON workflow.workflow_definitions IS 'Sets updated_at (and updated_by_user_id from the session) on every update.';

-- ---------------------------------------------------------------- workflow_states
CREATE TABLE workflow.workflow_states (
    id                      bigint GENERATED BY DEFAULT AS IDENTITY,
    tenant_id               bigint       NOT NULL DEFAULT core.fn_current_tenant(),
    definition_id           bigint       NOT NULL,
    code                    varchar(50)  NOT NULL,
    name                    varchar(150) NOT NULL,
    description             text,
    state_kind              varchar(20)  NOT NULL DEFAULT 'intermediate',
    is_billable_point       boolean      NOT NULL DEFAULT false,
    is_client_visible       boolean      NOT NULL DEFAULT true,
    client_facing_state_id  bigint,
    client_label            varchar(150),
    is_approval_gate        boolean      NOT NULL DEFAULT false,
    sla_minutes             integer,
    sla_calendar_id         bigint,
    sort_order              integer      NOT NULL DEFAULT 0,
    legacy_id               bigint,
    legacy_source           varchar(64),
    legacy_key              varchar(200),
    created_at              timestamptz  NOT NULL DEFAULT now(),
    updated_at              timestamptz  NOT NULL DEFAULT now(),
    created_by_user_id      bigint,
    updated_by_user_id      bigint,
    CONSTRAINT pk_workflow_states PRIMARY KEY (id),
    CONSTRAINT uq_workflow_states__definition_id__code UNIQUE (definition_id, code),
    CONSTRAINT uq_workflow_states__definition_id__id UNIQUE (definition_id, id),
    CONSTRAINT fk_workflow_states__definition_id FOREIGN KEY (definition_id)
        REFERENCES workflow.workflow_definitions (id) ON DELETE CASCADE,
    CONSTRAINT fk_workflow_states__client_facing_state FOREIGN KEY (definition_id, client_facing_state_id)
        REFERENCES workflow.workflow_states (definition_id, id) ON DELETE NO ACTION,
    CONSTRAINT ck_workflow_states__state_kind CHECK (state_kind IN ('initial', 'intermediate', 'terminal', 'error')),
    CONSTRAINT ck_workflow_states__sla_positive CHECK (sla_minutes IS NULL OR sla_minutes > 0),
    CONSTRAINT ck_workflow_states__calendar_needs_sla CHECK (sla_calendar_id IS NULL OR sla_minutes IS NOT NULL),
    CONSTRAINT ck_workflow_states__not_own_client_state CHECK (client_facing_state_id IS NULL OR client_facing_state_id <> id)
);
CREATE UNIQUE INDEX uq_workflow_states__legacy ON workflow.workflow_states (legacy_source, legacy_id, COALESCE(legacy_key, ''))
    WHERE legacy_id IS NOT NULL OR legacy_key IS NOT NULL;
CREATE INDEX ix_workflow_states__definition_id__client_facing_state_id ON workflow.workflow_states (definition_id, client_facing_state_id)
    WHERE client_facing_state_id IS NOT NULL;
CREATE INDEX ix_workflow_states__sla_calendar_id ON workflow.workflow_states (sla_calendar_id) WHERE sla_calendar_id IS NOT NULL;

COMMENT ON TABLE workflow.workflow_states IS 'One state of a workflow definition (legacy OrdersFlow row / ordersStatus.json status), with what it means for billing, the client portal, approval and SLA. States belong to exactly one definition; staff-only states roll up to a client-facing state of the same definition. Configuration; deleted only with its definition and only while no instance or history uses it.';
COMMENT ON COLUMN workflow.workflow_states.id IS 'Surrogate key of the state; system-generated.';
COMMENT ON COLUMN workflow.workflow_states.tenant_id IS 'Owning tenant (core.tenants); filtered by RLS; equals the definition''s tenant.';
COMMENT ON COLUMN workflow.workflow_states.definition_id IS 'Definition the state belongs to (workflow.workflow_definitions).';
COMMENT ON COLUMN workflow.workflow_states.code IS 'Machine code of the state, unique within its definition (slug of the legacy status name, or ''cancelled'' / ''on_hold'' added by the ETL).';
COMMENT ON COLUMN workflow.workflow_states.name IS 'Staff-facing state name, e.g. "TIn Waiting components" (legacy OrdersFlow.Status).';
COMMENT ON COLUMN workflow.workflow_states.description IS 'What happens in this state (OrdersFlow.Description); user input. NULL = no description.';
COMMENT ON COLUMN workflow.workflow_states.state_kind IS 'Role of the state in the flow: ''initial'' = where a new instance starts; ''intermediate'' = work in progress; ''terminal'' = the flow is finished (done, cancelled); ''error'' = an exception state needing intervention.';
COMMENT ON COLUMN workflow.workflow_states.is_billable_point IS 'True = reaching this state makes the item chargeable (charging is triggered here).';
COMMENT ON COLUMN workflow.workflow_states.is_client_visible IS 'True = the client portal shows this state as is; false = staff-only state that the client sees as client_facing_state_id (e.g. Final AoX "TIn Ready" shown as "TIn Production").';
COMMENT ON COLUMN workflow.workflow_states.client_facing_state_id IS 'State of the same definition shown to the client instead of this one. NULL = shown as itself (client-visible) or not shown at all.';
COMMENT ON COLUMN workflow.workflow_states.client_label IS 'Label shown to the client when it differs from name (ordersStatus.json statusReadableName). NULL = use name.';
COMMENT ON COLUMN workflow.workflow_states.is_approval_gate IS 'True = progress stops here until the client approves (design, try-in, Ti-bar design, Ti-bar for Final AoX); the approval itself is orders.order_item_decisions.';
COMMENT ON COLUMN workflow.workflow_states.sla_minutes IS 'Target time an item may stay in this state, in minutes (e.g. 60 for a digital design, 2880 for 48 hours); > 0. Counted in working minutes of sla_calendar_id when set, else wall-clock minutes. NULL = no SLA for this state.';
COMMENT ON COLUMN workflow.workflow_states.sla_calendar_id IS 'Business calendar (core.business_calendars, e.g. Boston working hours) the SLA is measured on. NULL = SLA counted in wall-clock minutes, or no SLA.';
COMMENT ON COLUMN workflow.workflow_states.sort_order IS 'Display and progression order of the state within its definition (ascending).';
COMMENT ON COLUMN workflow.workflow_states.legacy_id IS 'Source row id (OrdersFlow.ID — the legacy status id). NULL = state added in threeddx3 or by the ETL.';
COMMENT ON COLUMN workflow.workflow_states.legacy_source IS 'Source: ''OrdersFlow'', ''ec2:ordersStatus.json'' or ''derived''. NULL = created in threeddx3.';
COMMENT ON COLUMN workflow.workflow_states.legacy_key IS 'Composite source key ''<OrderType>|<isDigital>|<serviceID>|<ID>'' (OrdersFlow primary key is (ID, OrderType, isDigital), so ID alone is not unique). NULL = not migrated.';
COMMENT ON COLUMN workflow.workflow_states.created_at IS 'UTC instant the row was created; system-generated. [AUDIT]';
COMMENT ON COLUMN workflow.workflow_states.updated_at IS 'UTC instant of the last change; maintained by trg_workflow_states__touch_updated_at. [AUDIT]';
COMMENT ON COLUMN workflow.workflow_states.created_by_user_id IS 'Staff user who created the state; no FK by design. NULL = system or migration. [AUDIT]';
COMMENT ON COLUMN workflow.workflow_states.updated_by_user_id IS 'Staff user who last changed the state; no FK by design. NULL = system or never changed. [AUDIT]';
COMMENT ON CONSTRAINT pk_workflow_states ON workflow.workflow_states IS 'One row per state.';
COMMENT ON CONSTRAINT uq_workflow_states__definition_id__code ON workflow.workflow_states IS 'A state code is unique within its definition; the ETL upserts on (definition_id, code).';
COMMENT ON CONSTRAINT uq_workflow_states__definition_id__id ON workflow.workflow_states IS 'Target of the composite FKs that force every state reference (transitions, client-facing state, instances, legacy codes) to stay inside the same definition.';
COMMENT ON CONSTRAINT fk_workflow_states__definition_id ON workflow.workflow_states IS 'States are part of their definition and go with it (blocked in practice once instances or history reference them).';
COMMENT ON CONSTRAINT fk_workflow_states__client_facing_state ON workflow.workflow_states IS 'The client-facing roll-up state belongs to the same definition; it cannot be deleted while staff states roll up to it. NO ACTION (checked at statement end) rather than RESTRICT so deleting a whole definition, which cascades to all its states at once, is not blocked by references among those states.';
COMMENT ON CONSTRAINT ck_workflow_states__state_kind ON workflow.workflow_states IS 'A state is initial, intermediate, terminal or error.';
COMMENT ON CONSTRAINT ck_workflow_states__sla_positive ON workflow.workflow_states IS 'An SLA, when set, is a positive number of minutes.';
COMMENT ON CONSTRAINT ck_workflow_states__calendar_needs_sla ON workflow.workflow_states IS 'A business calendar only has meaning for a state that has an SLA.';
COMMENT ON CONSTRAINT ck_workflow_states__not_own_client_state ON workflow.workflow_states IS 'A state cannot roll up to itself.';
COMMENT ON INDEX workflow.uq_workflow_states__legacy IS 'Every migrated state is traceable to its OrdersFlow row and cannot be loaded twice.';
COMMENT ON INDEX workflow.ix_workflow_states__definition_id__client_facing_state_id IS 'Staff states rolling up to a client state; covers the composite FK.';
COMMENT ON INDEX workflow.ix_workflow_states__sla_calendar_id IS 'States measured on a calendar (calendar change impact); covers the FK to core.business_calendars.';
CREATE TRIGGER trg_workflow_states__touch_updated_at BEFORE UPDATE ON workflow.workflow_states
    FOR EACH ROW EXECUTE FUNCTION core.fn_touch_updated_at();
COMMENT ON TRIGGER trg_workflow_states__touch_updated_at ON workflow.workflow_states IS 'Sets updated_at (and updated_by_user_id from the session) on every update.';

-- ---------------------------------------------------------------- workflow_transitions
CREATE TABLE workflow.workflow_transitions (
    id                      bigint GENERATED BY DEFAULT AS IDENTITY,
    tenant_id               bigint       NOT NULL DEFAULT core.fn_current_tenant(),
    definition_id           bigint       NOT NULL,
    from_state_id           bigint,
    to_state_id             bigint       NOT NULL,
    name                    varchar(150),
    required_capability_id  bigint,
    guard_condition         jsonb        NOT NULL DEFAULT '{}'::jsonb,
    auto_trigger            varchar(100),
    legacy_id               bigint,
    legacy_source           varchar(64),
    legacy_key              varchar(200),
    created_at              timestamptz  NOT NULL DEFAULT now(),
    updated_at              timestamptz  NOT NULL DEFAULT now(),
    created_by_user_id      bigint,
    updated_by_user_id      bigint,
    CONSTRAINT pk_workflow_transitions PRIMARY KEY (id),
    CONSTRAINT uq_workflow_transitions__definition__from__to UNIQUE NULLS NOT DISTINCT (definition_id, from_state_id, to_state_id),
    CONSTRAINT fk_workflow_transitions__definition_id FOREIGN KEY (definition_id)
        REFERENCES workflow.workflow_definitions (id) ON DELETE CASCADE,
    CONSTRAINT fk_workflow_transitions__from_state FOREIGN KEY (definition_id, from_state_id)
        REFERENCES workflow.workflow_states (definition_id, id) ON DELETE CASCADE,
    CONSTRAINT fk_workflow_transitions__to_state FOREIGN KEY (definition_id, to_state_id)
        REFERENCES workflow.workflow_states (definition_id, id) ON DELETE CASCADE,
    CONSTRAINT ck_workflow_transitions__not_self CHECK (from_state_id IS NULL OR from_state_id <> to_state_id)
);
CREATE UNIQUE INDEX uq_workflow_transitions__legacy ON workflow.workflow_transitions (legacy_source, legacy_id, COALESCE(legacy_key, ''))
    WHERE legacy_id IS NOT NULL OR legacy_key IS NOT NULL;
CREATE INDEX ix_workflow_transitions__definition_id__to_state_id ON workflow.workflow_transitions (definition_id, to_state_id);
CREATE INDEX ix_workflow_transitions__required_capability_id ON workflow.workflow_transitions (required_capability_id) WHERE required_capability_id IS NOT NULL;

COMMENT ON TABLE workflow.workflow_transitions IS 'An allowed move between two states of the same definition (legacy OrdersFlow.NextStatus, plus "from any state" cancel and on-hold). The V100 transition validator rejects any state change on an instance that has no matching row. Configuration; goes with its definition or states.';
COMMENT ON COLUMN workflow.workflow_transitions.id IS 'Surrogate key of the transition; system-generated.';
COMMENT ON COLUMN workflow.workflow_transitions.tenant_id IS 'Owning tenant (core.tenants); filtered by RLS.';
COMMENT ON COLUMN workflow.workflow_transitions.definition_id IS 'Definition the transition belongs to (workflow.workflow_definitions).';
COMMENT ON COLUMN workflow.workflow_transitions.from_state_id IS 'State the move starts from, in the same definition. NULL = from any state (cancel and on-hold transitions).';
COMMENT ON COLUMN workflow.workflow_transitions.to_state_id IS 'State the move ends in, in the same definition.';
COMMENT ON COLUMN workflow.workflow_transitions.name IS 'Action label shown on the button, e.g. "advance", "cancelled", "Send to client". NULL = unnamed automatic advance.';
COMMENT ON COLUMN workflow.workflow_transitions.required_capability_id IS 'Capability (iam.capabilities) a user needs to perform the move, e.g. GUIDE_CONFIRM. NULL = anyone allowed to work the item may perform it.';
COMMENT ON COLUMN workflow.workflow_transitions.guard_condition IS 'Extra condition the validator evaluates before allowing the move (e.g. all files uploaded), as JSON; ''{}'' = no condition. Not filtered in SQL, so no GIN index.';
COMMENT ON COLUMN workflow.workflow_transitions.auto_trigger IS 'Event code that performs the move automatically (e.g. file_uploaded, payment_received). NULL = manual move only.';
COMMENT ON COLUMN workflow.workflow_transitions.legacy_id IS 'Source row id (OrdersFlow.ID of the from-state) when migrated. NULL = added in threeddx3 or derived.';
COMMENT ON COLUMN workflow.workflow_transitions.legacy_source IS 'Source: ''OrdersFlow'' or ''derived''. NULL = created in threeddx3.';
COMMENT ON COLUMN workflow.workflow_transitions.legacy_key IS 'Composite source key ''<OrderType>|<isDigital>|<serviceID>|<ID>-><NextStatus>''. NULL = not migrated.';
COMMENT ON COLUMN workflow.workflow_transitions.created_at IS 'UTC instant the row was created; system-generated. [AUDIT]';
COMMENT ON COLUMN workflow.workflow_transitions.updated_at IS 'UTC instant of the last change; maintained by trg_workflow_transitions__touch_updated_at. [AUDIT]';
COMMENT ON COLUMN workflow.workflow_transitions.created_by_user_id IS 'Staff user who created the transition; no FK by design. NULL = system or migration. [AUDIT]';
COMMENT ON COLUMN workflow.workflow_transitions.updated_by_user_id IS 'Staff user who last changed the transition; no FK by design. NULL = system or never changed. [AUDIT]';
COMMENT ON CONSTRAINT pk_workflow_transitions ON workflow.workflow_transitions IS 'One row per allowed move.';
COMMENT ON CONSTRAINT uq_workflow_transitions__definition__from__to ON workflow.workflow_transitions IS 'A move between two states (or from any state, NULL counted as a value) is defined once per definition; the ETL upserts on (definition_id, from_state_id, to_state_id). Also covers the definition and from-state FKs.';
COMMENT ON CONSTRAINT fk_workflow_transitions__definition_id ON workflow.workflow_transitions IS 'Transitions are part of their definition and go with it.';
COMMENT ON CONSTRAINT fk_workflow_transitions__from_state ON workflow.workflow_transitions IS 'The from-state belongs to the same definition; the transition goes with the state.';
COMMENT ON CONSTRAINT fk_workflow_transitions__to_state ON workflow.workflow_transitions IS 'The to-state belongs to the same definition; the transition goes with the state.';
COMMENT ON CONSTRAINT ck_workflow_transitions__not_self ON workflow.workflow_transitions IS 'A transition changes the state; a state cannot transition to itself.';
COMMENT ON INDEX workflow.uq_workflow_transitions__legacy IS 'Every migrated transition is traceable and cannot be loaded twice.';
COMMENT ON INDEX workflow.ix_workflow_transitions__definition_id__to_state_id IS 'Transitions into a state (validator lookup by target state); covers the to-state composite FK.';
COMMENT ON INDEX workflow.ix_workflow_transitions__required_capability_id IS 'Transitions guarded by a capability (permission review); covers the FK to iam.capabilities.';
CREATE TRIGGER trg_workflow_transitions__touch_updated_at BEFORE UPDATE ON workflow.workflow_transitions
    FOR EACH ROW EXECUTE FUNCTION core.fn_touch_updated_at();
COMMENT ON TRIGGER trg_workflow_transitions__touch_updated_at ON workflow.workflow_transitions IS 'Sets updated_at (and updated_by_user_id from the session) on every update.';

-- ---------------------------------------------------------------- legacy_status_codes
CREATE TABLE workflow.legacy_status_codes (
    id                 bigint GENERATED BY DEFAULT AS IDENTITY,
    tenant_id          bigint       NOT NULL DEFAULT core.fn_current_tenant(),
    definition_id      bigint       NOT NULL,
    legacy_status_id   integer      NOT NULL,
    state_id           bigint       NOT NULL,
    label              varchar(255) NOT NULL,
    legacy_family      varchar(40),
    status_color       varchar(20),
    legacy_id          bigint,
    legacy_source      varchar(64)  NOT NULL,
    legacy_key         varchar(200),
    created_at         timestamptz  NOT NULL DEFAULT now(),
    CONSTRAINT pk_legacy_status_codes PRIMARY KEY (id),
    CONSTRAINT uq_legacy_status_codes__definition_id__legacy_status_id UNIQUE (definition_id, legacy_status_id),
    CONSTRAINT fk_legacy_status_codes__definition_id FOREIGN KEY (definition_id)
        REFERENCES workflow.workflow_definitions (id) ON DELETE CASCADE,
    CONSTRAINT fk_legacy_status_codes__state FOREIGN KEY (definition_id, state_id)
        REFERENCES workflow.workflow_states (definition_id, id) ON DELETE CASCADE,
    CONSTRAINT ck_legacy_status_codes__legacy_source CHECK (legacy_source IN ('OrdersFlow', 'ec2:ordersStatus.json'))
);
CREATE UNIQUE INDEX uq_legacy_status_codes__legacy ON workflow.legacy_status_codes (legacy_source, legacy_id, COALESCE(legacy_key, ''))
    WHERE legacy_id IS NOT NULL OR legacy_key IS NOT NULL;
CREATE INDEX ix_legacy_status_codes__definition_id__state_id ON workflow.legacy_status_codes (definition_id, state_id);

COMMENT ON TABLE workflow.legacy_status_codes IS 'Translation of a legacy numeric status code into a state, per definition: the same legacy code means different things on different product lines (GFMR and Other both reuse 138/145; ordersStatus.json reuses 1-11 and 21-24 across families), so the key is (definition, legacy status id). Seeded by the ETL from OrdersFlow and ec2 statics/ordersStatus.json (97 statuses in 15 families); used to load item status history and to answer legacy-code questions. Configuration; goes with its definition.';
COMMENT ON COLUMN workflow.legacy_status_codes.id IS 'Surrogate key of the mapping row; system-generated.';
COMMENT ON COLUMN workflow.legacy_status_codes.tenant_id IS 'Owning tenant (core.tenants); filtered by RLS.';
COMMENT ON COLUMN workflow.legacy_status_codes.definition_id IS 'Definition (service flow) in which the legacy code has this meaning.';
COMMENT ON COLUMN workflow.legacy_status_codes.legacy_status_id IS 'Legacy numeric status code as stored on legacy order/sub-order rows (OrdersFlow.ID / ordersStatus.json statusID).';
COMMENT ON COLUMN workflow.legacy_status_codes.state_id IS 'State of the same definition the code maps to.';
COMMENT ON COLUMN workflow.legacy_status_codes.label IS 'Legacy label of the code as the source shows it (OrdersFlow.Status, or ordersStatus.json statusName), kept verbatim for reconciliation. [SNAPSHOT]';
COMMENT ON COLUMN workflow.legacy_status_codes.legacy_family IS 'ordersStatus.json family (group) the code was read from, verbatim, e.g. ''Treat.plan'', ''GFMR'', ''Miscellaneuos''. NULL = code read from OrdersFlow, which has no family name.';
COMMENT ON COLUMN workflow.legacy_status_codes.status_color IS 'Display colour the legacy UI used for the code (ordersStatus.json statusColor), verbatim. NULL = no colour in the source.';
COMMENT ON COLUMN workflow.legacy_status_codes.legacy_id IS 'Source row id (OrdersFlow.ID) when read from OrdersFlow. NULL = read from ordersStatus.json (see legacy_key).';
COMMENT ON COLUMN workflow.legacy_status_codes.legacy_source IS 'Where the code was read from: ''OrdersFlow'' = the legacy flow table (authoritative when both sources have the code); ''ec2:ordersStatus.json'' = the ec2 statics vocabulary file, for codes OrdersFlow lacks.';
COMMENT ON COLUMN workflow.legacy_status_codes.legacy_key IS 'Composite source key: ''<family>|<statusID>'' for ordersStatus.json, ''<OrderType>|<isDigital>|<serviceID>|<ID>'' for OrdersFlow. NULL = legacy_id is sufficient.';
COMMENT ON COLUMN workflow.legacy_status_codes.created_at IS 'UTC instant the mapping was loaded; system-generated. [AUDIT]';
COMMENT ON CONSTRAINT pk_legacy_status_codes ON workflow.legacy_status_codes IS 'One row per mapping.';
COMMENT ON CONSTRAINT uq_legacy_status_codes__definition_id__legacy_status_id ON workflow.legacy_status_codes IS 'Within one service flow a legacy status code has exactly one meaning; also covers the definition FK.';
COMMENT ON CONSTRAINT fk_legacy_status_codes__definition_id ON workflow.legacy_status_codes IS 'Mappings are part of their definition and go with it.';
COMMENT ON CONSTRAINT fk_legacy_status_codes__state ON workflow.legacy_status_codes IS 'A legacy code maps to a state of the same definition, never to a state of another flow.';
COMMENT ON CONSTRAINT ck_legacy_status_codes__legacy_source ON workflow.legacy_status_codes IS 'Legacy codes come only from OrdersFlow or ordersStatus.json.';
COMMENT ON INDEX workflow.uq_legacy_status_codes__legacy IS 'Every mapping is traceable to its source and cannot be loaded twice.';
COMMENT ON INDEX workflow.ix_legacy_status_codes__definition_id__state_id IS 'Legacy codes that map to a state (reverse lookup); covers the composite state FK.';

-- ---------------------------------------------------------------- workflow_instances
CREATE TABLE workflow.workflow_instances (
    id                 bigint GENERATED BY DEFAULT AS IDENTITY,
    tenant_id          bigint       NOT NULL DEFAULT core.fn_current_tenant(),
    definition_id      bigint       NOT NULL,
    entity_type        varchar(50)  NOT NULL,
    entity_id          bigint       NOT NULL,
    track              varchar(50)  NOT NULL DEFAULT 'main',
    current_state_id   bigint,
    started_at         timestamptz  NOT NULL DEFAULT now(),
    completed_at       timestamptz,
    due_at             timestamptz,
    is_overdue         boolean      NOT NULL DEFAULT false,
    metadata           jsonb        NOT NULL DEFAULT '{}'::jsonb,
    created_at         timestamptz  NOT NULL DEFAULT now(),
    updated_at         timestamptz  NOT NULL DEFAULT now(),
    created_by_user_id bigint,
    updated_by_user_id bigint,
    CONSTRAINT pk_workflow_instances PRIMARY KEY (id),
    CONSTRAINT uq_workflow_instances__entity__definition__track UNIQUE (entity_type, entity_id, definition_id, track),
    CONSTRAINT fk_workflow_instances__definition_id FOREIGN KEY (definition_id)
        REFERENCES workflow.workflow_definitions (id) ON DELETE RESTRICT,
    CONSTRAINT fk_workflow_instances__current_state FOREIGN KEY (definition_id, current_state_id)
        REFERENCES workflow.workflow_states (definition_id, id) ON DELETE RESTRICT,
    CONSTRAINT ck_workflow_instances__entity_type CHECK (entity_type IN ('order', 'order_item', 'task', 'voucher', 'shipment', 'production_job', 'qc_inspection')),
    CONSTRAINT ck_workflow_instances__track_not_blank CHECK (btrim(track) <> ''),
    CONSTRAINT ck_workflow_instances__completed_after_start CHECK (completed_at IS NULL OR completed_at >= started_at)
);
CREATE INDEX ix_workflow_instances__definition_id__current_state_id ON workflow.workflow_instances (definition_id, current_state_id);
CREATE INDEX ix_workflow_instances__tenant_id__due_at__open ON workflow.workflow_instances (tenant_id, due_at)
    WHERE completed_at IS NULL AND due_at IS NOT NULL;

COMMENT ON TABLE workflow.workflow_instances IS 'One run of a workflow definition for one entity (usually an order item) on one track: where it is now, when it started and finished, and its SLA due time. An item may run several tracks at once (Final AoX: Try-In, Ti Bar and Zirconia in parallel). Each open legacy item gets the definition of its own (order type, isDigital, serviceID) and its mapped current state (review F05), not the first definition. State changes are validated by the V100 trigger, which writes workflow_history.';
COMMENT ON COLUMN workflow.workflow_instances.id IS 'Surrogate key of the instance; system-generated.';
COMMENT ON COLUMN workflow.workflow_instances.tenant_id IS 'Owning tenant (core.tenants); filtered by RLS.';
COMMENT ON COLUMN workflow.workflow_instances.definition_id IS 'Definition being run (workflow.workflow_definitions); cannot be deleted while instances exist.';
COMMENT ON COLUMN workflow.workflow_instances.entity_type IS 'Kind of entity the instance drives, same values as workflow_definitions.entity_type: ''order'', ''order_item'', ''task'', ''voucher'', ''shipment'', ''production_job'', ''qc_inspection''.';
COMMENT ON COLUMN workflow.workflow_instances.entity_id IS 'Id of the driven row in the table named by entity_type (e.g. orders.order_items.id). Polymorphic, so no FK; the V100 functions check existence.';
COMMENT ON COLUMN workflow.workflow_instances.track IS 'Parallel track name within the item, e.g. ''main'', ''try_in'', ''ti_bar'', ''zirconia''; not blank.';
COMMENT ON COLUMN workflow.workflow_instances.current_state_id IS 'State the instance is in now, of the same definition. NULL = not yet placed in a state (instance created before its initial state is resolved, e.g. a legacy code with no mapping awaiting review).';
COMMENT ON COLUMN workflow.workflow_instances.started_at IS 'UTC instant the instance started (for migrated items, the item''s creation time).';
COMMENT ON COLUMN workflow.workflow_instances.completed_at IS 'UTC instant the instance reached a terminal state; not before started_at. NULL = still running.';
COMMENT ON COLUMN workflow.workflow_instances.due_at IS 'UTC instant the current state''s SLA expires (state entry + sla_minutes on its calendar). NULL = current state has no SLA.';
COMMENT ON COLUMN workflow.workflow_instances.is_overdue IS 'True = due_at has passed while the instance is still in the state; set by the SLA job (V100).';
COMMENT ON COLUMN workflow.workflow_instances.metadata IS 'Engine bookkeeping for the run (e.g. the legacy status code it was loaded from). Not filtered or reported on, so no GIN index.';
COMMENT ON COLUMN workflow.workflow_instances.created_at IS 'UTC instant the row was created; system-generated. [AUDIT]';
COMMENT ON COLUMN workflow.workflow_instances.updated_at IS 'UTC instant of the last change (every state change); maintained by trg_workflow_instances__touch_updated_at. [AUDIT]';
COMMENT ON COLUMN workflow.workflow_instances.created_by_user_id IS 'User who started the instance; no FK by design. NULL = system or migration. [AUDIT]';
COMMENT ON COLUMN workflow.workflow_instances.updated_by_user_id IS 'User who last moved the instance; no FK by design. NULL = system or migration. [AUDIT]';
COMMENT ON CONSTRAINT pk_workflow_instances ON workflow.workflow_instances IS 'One row per instance.';
COMMENT ON CONSTRAINT uq_workflow_instances__entity__definition__track ON workflow.workflow_instances IS 'An entity runs a given definition at most once per track; ON CONFLICT must name all four columns (v2 defect 39). Also serves "instances of this entity".';
COMMENT ON CONSTRAINT fk_workflow_instances__definition_id ON workflow.workflow_instances IS 'A definition with running or finished instances cannot be deleted (history).';
COMMENT ON CONSTRAINT fk_workflow_instances__current_state ON workflow.workflow_instances IS 'The current state belongs to the instance''s own definition; a state in use cannot be deleted.';
COMMENT ON CONSTRAINT ck_workflow_instances__entity_type ON workflow.workflow_instances IS 'An instance drives one of the seven entity kinds the engine knows.';
COMMENT ON CONSTRAINT ck_workflow_instances__track_not_blank ON workflow.workflow_instances IS 'A track has a name.';
COMMENT ON CONSTRAINT ck_workflow_instances__completed_after_start ON workflow.workflow_instances IS 'An instance cannot finish before it started.';
COMMENT ON INDEX workflow.ix_workflow_instances__definition_id__current_state_id IS 'Work queues: items currently in a state of a flow; covers the definition and composite current-state FKs.';
COMMENT ON INDEX workflow.ix_workflow_instances__tenant_id__due_at__open IS 'SLA job and overdue dashboards over running instances only.';
CREATE TRIGGER trg_workflow_instances__touch_updated_at BEFORE UPDATE ON workflow.workflow_instances
    FOR EACH ROW EXECUTE FUNCTION core.fn_touch_updated_at();
COMMENT ON TRIGGER trg_workflow_instances__touch_updated_at ON workflow.workflow_instances IS 'Sets updated_at (and updated_by_user_id from the session) on every update.';

-- ---------------------------------------------------------------- workflow_history
CREATE TABLE workflow.workflow_history (
    id                 bigint GENERATED BY DEFAULT AS IDENTITY,
    tenant_id          bigint       NOT NULL DEFAULT core.fn_current_tenant(),
    instance_id        bigint       NOT NULL,
    from_state_id      bigint,
    to_state_id        bigint       NOT NULL,
    transition_id      bigint,
    comment            text,
    duration_seconds   bigint,
    actor_kind         core.actor_kind NOT NULL DEFAULT 'user',
    actor_user_id      bigint,
    actor_role_id      bigint,
    occurred_at        timestamptz  NOT NULL DEFAULT now(),
    legacy_id          bigint,
    legacy_source      varchar(64),
    legacy_key         varchar(200),
    CONSTRAINT pk_workflow_history PRIMARY KEY (id),
    CONSTRAINT fk_workflow_history__instance_id FOREIGN KEY (instance_id)
        REFERENCES workflow.workflow_instances (id) ON DELETE RESTRICT,
    CONSTRAINT fk_workflow_history__from_state_id FOREIGN KEY (from_state_id)
        REFERENCES workflow.workflow_states (id) ON DELETE RESTRICT,
    CONSTRAINT fk_workflow_history__to_state_id FOREIGN KEY (to_state_id)
        REFERENCES workflow.workflow_states (id) ON DELETE RESTRICT,
    CONSTRAINT fk_workflow_history__transition_id FOREIGN KEY (transition_id)
        REFERENCES workflow.workflow_transitions (id) ON DELETE RESTRICT,
    CONSTRAINT ck_workflow_history__duration_non_negative CHECK (duration_seconds IS NULL OR duration_seconds >= 0),
    CONSTRAINT ck_workflow_history__state_changed CHECK (from_state_id IS NULL OR from_state_id <> to_state_id)
);
CREATE UNIQUE INDEX uq_workflow_history__legacy ON workflow.workflow_history (legacy_source, legacy_id, COALESCE(legacy_key, ''))
    WHERE legacy_id IS NOT NULL OR legacy_key IS NOT NULL;
CREATE INDEX ix_workflow_history__instance_id__occurred_at ON workflow.workflow_history (instance_id, occurred_at);
CREATE INDEX ix_workflow_history__from_state_id ON workflow.workflow_history (from_state_id) WHERE from_state_id IS NOT NULL;
CREATE INDEX ix_workflow_history__to_state_id__occurred_at ON workflow.workflow_history (to_state_id, occurred_at);
CREATE INDEX ix_workflow_history__transition_id ON workflow.workflow_history (transition_id) WHERE transition_id IS NOT NULL;
CREATE INDEX ix_workflow_history__tenant_id__occurred_at__id ON workflow.workflow_history (tenant_id, occurred_at, id);

COMMENT ON TABLE workflow.workflow_history IS 'Every state change of a workflow instance: from, to, which transition, who (user and the role they acted in), when, and how long the instance spent in the previous state. Written by the V100 transition trigger, so history can never diverge from the current state; migrated from legacy status history tables. Append-only (trg_workflow_history__append_only); corrections are new rows. Large (millions of rows).';
COMMENT ON COLUMN workflow.workflow_history.id IS 'Surrogate key of the history row; system-generated.';
COMMENT ON COLUMN workflow.workflow_history.tenant_id IS 'Owning tenant (core.tenants); filtered by RLS.';
COMMENT ON COLUMN workflow.workflow_history.instance_id IS 'Instance that changed state (workflow.workflow_instances).';
COMMENT ON COLUMN workflow.workflow_history.from_state_id IS 'State before the change. NULL = the instance''s first placement (start).';
COMMENT ON COLUMN workflow.workflow_history.to_state_id IS 'State the instance entered with this change (workflow.workflow_states).';
COMMENT ON COLUMN workflow.workflow_history.transition_id IS 'Transition rule that allowed the change. NULL = migrated history recorded before transitions were enforced, or an administrative correction.';
COMMENT ON COLUMN workflow.workflow_history.comment IS 'Note entered with the change; free text that may name a patient. NULL = no note. [PHI-RISK]';
COMMENT ON COLUMN workflow.workflow_history.duration_seconds IS 'Seconds the instance spent in from_state before this change, precomputed so "average time in design" needs no window function over millions of rows; never negative. NULL = first placement (no previous state) or unknown for migrated rows.';
COMMENT ON COLUMN workflow.workflow_history.actor_kind IS 'Who made the change (core.actor_kind): ''user'', ''system'' (job, trigger, migration), ''integration'' (e.g. Relu webhook) or ''anonymous'' (client confirmation link).';
COMMENT ON COLUMN workflow.workflow_history.actor_user_id IS 'User who made the change (iam.users id). No FK by design: append-only history must survive user deletion and cannot be SET NULL. NULL = not a user action.';
COMMENT ON COLUMN workflow.workflow_history.actor_role_id IS 'Role the user acted in at the time (iam.roles id, from core.fn_current_role_id()), e.g. Prepper or Design QC (D3 GAP-071). No FK by design, same reason as actor_user_id. NULL = not a user action, or role not recorded (all migrated rows).';
COMMENT ON COLUMN workflow.workflow_history.occurred_at IS 'UTC instant of the state change (legacy times converted from America/New_York). [AUDIT]';
COMMENT ON COLUMN workflow.workflow_history.legacy_id IS 'Source row id when migrated (e.g. service_status_history.id). NULL = created in threeddx3.';
COMMENT ON COLUMN workflow.workflow_history.legacy_source IS 'Source table when migrated (e.g. ''service_status_history'', ''OrderHistory'', ''PendingStatusHistory''). NULL = created in threeddx3.';
COMMENT ON COLUMN workflow.workflow_history.legacy_key IS 'Composite source key when one id is not enough. NULL = legacy_id is sufficient or not migrated.';
COMMENT ON CONSTRAINT pk_workflow_history ON workflow.workflow_history IS 'One row per state change.';
COMMENT ON CONSTRAINT fk_workflow_history__instance_id ON workflow.workflow_history IS 'An instance with history cannot be deleted (history; append-only rows cannot cascade).';
COMMENT ON CONSTRAINT fk_workflow_history__from_state_id ON workflow.workflow_history IS 'A state that appears in history cannot be deleted.';
COMMENT ON CONSTRAINT fk_workflow_history__to_state_id ON workflow.workflow_history IS 'A state that appears in history cannot be deleted.';
COMMENT ON CONSTRAINT fk_workflow_history__transition_id ON workflow.workflow_history IS 'A transition that appears in history cannot be deleted (append-only rows cannot be SET NULL).';
COMMENT ON CONSTRAINT ck_workflow_history__duration_non_negative ON workflow.workflow_history IS 'Time spent in a state is never negative.';
COMMENT ON CONSTRAINT ck_workflow_history__state_changed ON workflow.workflow_history IS 'A history row records an actual change of state.';
COMMENT ON INDEX workflow.uq_workflow_history__legacy IS 'Every migrated history row is traceable and cannot be loaded twice.';
COMMENT ON INDEX workflow.ix_workflow_history__instance_id__occurred_at IS 'Timeline of one instance and the "time since last change" lookup; covers the FK.';
COMMENT ON INDEX workflow.ix_workflow_history__from_state_id IS 'Time-in-state reports by state left; covers the FK.';
COMMENT ON INDEX workflow.ix_workflow_history__to_state_id__occurred_at IS 'Throughput reports: items entering a state per period; covers the FK.';
COMMENT ON INDEX workflow.ix_workflow_history__transition_id IS 'Use of a transition; covers the FK.';
COMMENT ON INDEX workflow.ix_workflow_history__tenant_id__occurred_at__id IS 'Stable keyset pagination and period reports over the whole history.';
CREATE TRIGGER trg_workflow_history__append_only BEFORE UPDATE OR DELETE ON workflow.workflow_history
    FOR EACH ROW EXECUTE FUNCTION core.fn_reject_mutation();
COMMENT ON TRIGGER trg_workflow_history__append_only ON workflow.workflow_history IS 'Workflow history is append-only: UPDATE and DELETE are rejected.';

-- ---------------------------------------------------------------- task_types
CREATE TABLE workflow.task_types (
    id                 bigint GENERATED BY DEFAULT AS IDENTITY,
    tenant_id          bigint       NOT NULL DEFAULT core.fn_current_tenant(),
    code               core.entity_code NOT NULL,
    name               varchar(150) NOT NULL,
    owning_team_id     bigint,
    default_sla_hours  integer,
    is_active          boolean      NOT NULL DEFAULT true,
    legacy_id          bigint,
    legacy_source      varchar(64),
    legacy_key         varchar(200),
    created_at         timestamptz  NOT NULL DEFAULT now(),
    updated_at         timestamptz  NOT NULL DEFAULT now(),
    created_by_user_id bigint,
    updated_by_user_id bigint,
    CONSTRAINT pk_task_types PRIMARY KEY (id),
    CONSTRAINT uq_task_types__tenant_id__code UNIQUE (tenant_id, code),
    CONSTRAINT ck_task_types__sla_positive CHECK (default_sla_hours IS NULL OR default_sla_hours > 0)
);
CREATE UNIQUE INDEX uq_task_types__legacy ON workflow.task_types (legacy_source, legacy_id, COALESCE(legacy_key, ''))
    WHERE legacy_id IS NOT NULL OR legacy_key IS NOT NULL;
CREATE INDEX ix_task_types__owning_team_id ON workflow.task_types (owning_team_id) WHERE owning_team_id IS NOT NULL;

COMMENT ON TABLE workflow.task_types IS 'Kinds of company-wide task (cs_review, finance_approval, design_review, kit_preparation, shipment_tracking, client_follow_up, legacy) with the team that owns them and their default SLA. Master data; deactivate, do not delete.';
COMMENT ON COLUMN workflow.task_types.id IS 'Surrogate key of the task type; system-generated.';
COMMENT ON COLUMN workflow.task_types.tenant_id IS 'Owning tenant (core.tenants); filtered by RLS.';
COMMENT ON COLUMN workflow.task_types.code IS 'Stable code of the task type, unique per tenant; the ETL upserts on it.';
COMMENT ON COLUMN workflow.task_types.name IS 'Display name of the task type, e.g. "CS Review".';
COMMENT ON COLUMN workflow.task_types.owning_team_id IS 'Team (iam.teams) that receives tasks of this type by default. NULL = no default team; tasks are assigned explicitly.';
COMMENT ON COLUMN workflow.task_types.default_sla_hours IS 'Default time to complete a task of this type, in wall-clock hours; > 0. NULL = no default SLA.';
COMMENT ON COLUMN workflow.task_types.is_active IS 'False = no new tasks of this type; existing tasks unaffected.';
COMMENT ON COLUMN workflow.task_types.legacy_id IS 'Source row id when migrated. NULL = seeded (legacy_source ''derived'') or created in threeddx3.';
COMMENT ON COLUMN workflow.task_types.legacy_source IS 'Source: ''derived'' (seeded by ETL stage 60) or a legacy table. NULL = created in threeddx3.';
COMMENT ON COLUMN workflow.task_types.legacy_key IS 'Composite source key when one id is not enough. NULL = not needed.';
COMMENT ON COLUMN workflow.task_types.created_at IS 'UTC instant the row was created; system-generated. [AUDIT]';
COMMENT ON COLUMN workflow.task_types.updated_at IS 'UTC instant of the last change; maintained by trg_task_types__touch_updated_at. [AUDIT]';
COMMENT ON COLUMN workflow.task_types.created_by_user_id IS 'Staff user who created the type; no FK by design. NULL = system or migration. [AUDIT]';
COMMENT ON COLUMN workflow.task_types.updated_by_user_id IS 'Staff user who last changed the type; no FK by design. NULL = system or never changed. [AUDIT]';
COMMENT ON CONSTRAINT pk_task_types ON workflow.task_types IS 'One row per task type.';
COMMENT ON CONSTRAINT uq_task_types__tenant_id__code ON workflow.task_types IS 'A task type code is unique within a tenant.';
COMMENT ON CONSTRAINT ck_task_types__sla_positive ON workflow.task_types IS 'A default SLA, when set, is a positive number of hours.';
COMMENT ON INDEX workflow.uq_task_types__legacy IS 'Every migrated task type is traceable and cannot be loaded twice.';
COMMENT ON INDEX workflow.ix_task_types__owning_team_id IS 'Task types owned by a team; covers the FK to iam.teams.';
CREATE TRIGGER trg_task_types__touch_updated_at BEFORE UPDATE ON workflow.task_types
    FOR EACH ROW EXECUTE FUNCTION core.fn_touch_updated_at();
COMMENT ON TRIGGER trg_task_types__touch_updated_at ON workflow.task_types IS 'Sets updated_at (and updated_by_user_id from the session) on every update.';

-- ---------------------------------------------------------------- tasks
CREATE TABLE workflow.tasks (
    id                   bigint GENERATED BY DEFAULT AS IDENTITY,
    uuid                 uuid         NOT NULL DEFAULT gen_random_uuid(),
    tenant_id            bigint       NOT NULL DEFAULT core.fn_current_tenant(),
    task_type_id         bigint,
    order_id             bigint,
    order_item_id        bigint,
    internal_history_id  bigint,
    contact_id           bigint,
    title                varchar(255) NOT NULL,
    description          text,
    state                workflow.task_state NOT NULL DEFAULT 'open',
    priority             varchar(20)  NOT NULL DEFAULT 'normal',
    due_at               timestamptz,
    original_due_at      timestamptz,
    closed_at            timestamptz,
    closed_by_user_id    bigint,
    close_reason         varchar(255),
    metadata             jsonb        NOT NULL DEFAULT '{}'::jsonb,
    legacy_id            bigint,
    legacy_source        varchar(64),
    legacy_key           varchar(200),
    created_at           timestamptz  NOT NULL DEFAULT now(),
    updated_at           timestamptz  NOT NULL DEFAULT now(),
    created_by_user_id   bigint,
    updated_by_user_id   bigint,
    CONSTRAINT pk_tasks PRIMARY KEY (id),
    CONSTRAINT uq_tasks__uuid UNIQUE (uuid),
    CONSTRAINT fk_tasks__task_type_id FOREIGN KEY (task_type_id)
        REFERENCES workflow.task_types (id) ON DELETE SET NULL,
    CONSTRAINT ck_tasks__item_requires_order CHECK (order_item_id IS NULL OR order_id IS NOT NULL),
    CONSTRAINT ck_tasks__priority CHECK (priority IN ('low', 'normal', 'high', 'urgent'))
);
CREATE UNIQUE INDEX uq_tasks__legacy ON workflow.tasks (legacy_source, legacy_id, COALESCE(legacy_key, ''))
    WHERE legacy_id IS NOT NULL OR legacy_key IS NOT NULL;
CREATE INDEX ix_tasks__tenant_id__created_at__id ON workflow.tasks (tenant_id, created_at, id);
CREATE INDEX ix_tasks__order_id__state ON workflow.tasks (order_id, state) WHERE order_id IS NOT NULL;
CREATE INDEX ix_tasks__order_item_id ON workflow.tasks (order_item_id) WHERE order_item_id IS NOT NULL;
CREATE INDEX ix_tasks__tenant_id__state__due_at__open ON workflow.tasks (tenant_id, state, due_at)
    WHERE state IN ('open', 'in_progress', 'blocked');
CREATE INDEX ix_tasks__task_type_id__created_at ON workflow.tasks (task_type_id, created_at) WHERE task_type_id IS NOT NULL;
CREATE INDEX ix_tasks__contact_id ON workflow.tasks (contact_id) WHERE contact_id IS NOT NULL;
CREATE INDEX ix_tasks__internal_history_id ON workflow.tasks (internal_history_id) WHERE internal_history_id IS NOT NULL;
CREATE INDEX ix_tasks__closed_by_user_id ON workflow.tasks (closed_by_user_id) WHERE closed_by_user_id IS NOT NULL;

COMMENT ON TABLE workflow.tasks IS 'A unit of work for a person or team (CS, Sales, Finance, Production), optionally about an order, one order item, a client, or raised from an internal-history note. Migrated from legacy Tasks (~625k rows). Lifecycle by state (open -> in_progress/blocked -> done/cancelled); no soft delete; a task with status history cannot be deleted. Description may name a patient.';
COMMENT ON COLUMN workflow.tasks.id IS 'Surrogate key of the task; system-generated.';
COMMENT ON COLUMN workflow.tasks.uuid IS 'Public identifier used by APIs and links; system-generated.';
COMMENT ON COLUMN workflow.tasks.tenant_id IS 'Owning tenant (core.tenants); filtered by RLS.';
COMMENT ON COLUMN workflow.tasks.task_type_id IS 'Kind of task (workflow.task_types); migrated tasks get ''legacy''. NULL = type removed or never classified.';
COMMENT ON COLUMN workflow.tasks.order_id IS 'Order the task is about (orders.orders; legacy Tasks.relatedToID). Required when order_item_id is set (derived from the item if the source order reference does not resolve, v2 defect 40). NULL = task not about an order.';
COMMENT ON COLUMN workflow.tasks.order_item_id IS 'Order item (service line) the task is about (orders.order_items), resolved from legacy (relatedToID or relatedToSubID, serviceID). NULL = order-level or non-order task.';
COMMENT ON COLUMN workflow.tasks.internal_history_id IS 'Internal-history note the task was raised from (collaboration.internal_history; legacy InternalHistoryTasks). NULL = not raised from a note.';
COMMENT ON COLUMN workflow.tasks.contact_id IS 'Client the task is about (crm.contacts). NULL = not about a specific client, or only through its order.';
COMMENT ON COLUMN workflow.tasks.title IS 'One-line summary shown in task lists (first 255 characters of the legacy description when no title existed). May name a patient. [PHI-RISK]';
COMMENT ON COLUMN workflow.tasks.description IS 'Full task text (legacy Tasks.description); user input that may name a patient. NULL = title says it all. [PHI-RISK]';
COMMENT ON COLUMN workflow.tasks.state IS 'Task state (workflow.task_state): ''open'' = created, not started; ''in_progress'' = being worked; ''blocked'' = waiting on someone else; ''done'' = completed; ''cancelled'' = no longer needed.';
COMMENT ON COLUMN workflow.tasks.priority IS 'Urgency: ''low'', ''normal'' (default), ''high'' or ''urgent''; legacy Tasks.priority text mapped by the ETL.';
COMMENT ON COLUMN workflow.tasks.due_at IS 'UTC instant the task is due (legacy Tasks.dueDate, a date, converted by stage 60); every change is recorded in task_due_date_changes with a reason. NULL = no due date (e.g. a Rush task).';
COMMENT ON COLUMN workflow.tasks.original_due_at IS 'Due time before it was first moved (legacy Tasks.swappedDeadline), kept for SLA reporting. NULL = due date never moved or not recorded. [SNAPSHOT]';
COMMENT ON COLUMN workflow.tasks.closed_at IS 'UTC instant the task was closed (done or cancelled; legacy Tasks.closeDate). NULL = still open.';
COMMENT ON COLUMN workflow.tasks.closed_by_user_id IS 'User who closed the task (iam.users; legacy Tasks.closeBy). NULL = still open, closed by the system, or closer unknown.';
COMMENT ON COLUMN workflow.tasks.close_reason IS 'Why the task was closed or cancelled; user input. NULL = no reason given.';
COMMENT ON COLUMN workflow.tasks.metadata IS 'Legacy task attributes with no column (Tasks.metaName / metaValue, relatedTo kind). Not filtered or reported on, so no GIN index.';
COMMENT ON COLUMN workflow.tasks.legacy_id IS 'Source row id (Tasks.taskID). NULL = created in threeddx3.';
COMMENT ON COLUMN workflow.tasks.legacy_source IS 'Source table (''Tasks''). NULL = created in threeddx3.';
COMMENT ON COLUMN workflow.tasks.legacy_key IS 'Composite source key when one id is not enough. NULL = legacy_id is sufficient or not migrated.';
COMMENT ON COLUMN workflow.tasks.created_at IS 'UTC instant the task was created (legacy Tasks.createdAt). [AUDIT]';
COMMENT ON COLUMN workflow.tasks.updated_at IS 'UTC instant of the last change; maintained by trg_tasks__touch_updated_at. [AUDIT]';
COMMENT ON COLUMN workflow.tasks.created_by_user_id IS 'User who created the task (legacy Tasks.createdBy); no FK by design (history must survive user deletion). NULL = system or creator unknown. [AUDIT]';
COMMENT ON COLUMN workflow.tasks.updated_by_user_id IS 'User who last changed the task; no FK by design. NULL = system, migration or never changed. [AUDIT]';
COMMENT ON CONSTRAINT pk_tasks ON workflow.tasks IS 'One row per task.';
COMMENT ON CONSTRAINT uq_tasks__uuid ON workflow.tasks IS 'The public identifier is unique.';
COMMENT ON CONSTRAINT fk_tasks__task_type_id ON workflow.tasks IS 'Removing a task type leaves its tasks unclassified rather than deleting work.';
COMMENT ON CONSTRAINT ck_tasks__item_requires_order ON workflow.tasks IS 'A task about an order item also names the item''s order (v2 defect 40: derive the order from the item).';
COMMENT ON CONSTRAINT ck_tasks__priority ON workflow.tasks IS 'Priority is one of low, normal, high, urgent.';
COMMENT ON INDEX workflow.uq_tasks__legacy IS 'Every migrated task is traceable to Tasks.taskID and cannot be loaded twice.';
COMMENT ON INDEX workflow.ix_tasks__tenant_id__created_at__id IS 'Stable keyset pagination of task lists by creation time.';
COMMENT ON INDEX workflow.ix_tasks__order_id__state IS 'Tasks of an order by state (order page); covers the FK to orders.orders.';
COMMENT ON INDEX workflow.ix_tasks__order_item_id IS 'Tasks of one order item; covers the FK to orders.order_items.';
COMMENT ON INDEX workflow.ix_tasks__tenant_id__state__due_at__open IS 'Open-task queues and overdue lists by due time (pending tasks only).';
COMMENT ON INDEX workflow.ix_tasks__task_type_id__created_at IS 'Tasks of a type over time (team workload reports); covers the FK.';
COMMENT ON INDEX workflow.ix_tasks__contact_id IS 'Tasks about a client (client page); covers the FK to crm.contacts.';
COMMENT ON INDEX workflow.ix_tasks__internal_history_id IS 'Tasks raised from a note; covers the FK to collaboration.internal_history.';
COMMENT ON INDEX workflow.ix_tasks__closed_by_user_id IS 'Tasks closed by a user (productivity reports); covers the FK to iam.users.';
CREATE TRIGGER trg_tasks__touch_updated_at BEFORE UPDATE ON workflow.tasks
    FOR EACH ROW EXECUTE FUNCTION core.fn_touch_updated_at();
COMMENT ON TRIGGER trg_tasks__touch_updated_at ON workflow.tasks IS 'Sets updated_at (and updated_by_user_id from the session) on every update.';

-- ---------------------------------------------------------------- task_assignments
CREATE TABLE workflow.task_assignments (
    id                   bigint GENERATED BY DEFAULT AS IDENTITY,
    tenant_id            bigint       NOT NULL DEFAULT core.fn_current_tenant(),
    task_id              bigint       NOT NULL,
    team_id              bigint,
    user_id              bigint,
    is_active            boolean      NOT NULL DEFAULT true,
    assigned_at          timestamptz  NOT NULL DEFAULT now(),
    assigned_by_user_id  bigint,
    unassigned_at        timestamptz,
    legacy_id            bigint,
    legacy_source        varchar(64),
    legacy_key           varchar(200),
    created_at           timestamptz  NOT NULL DEFAULT now(),
    CONSTRAINT pk_task_assignments PRIMARY KEY (id),
    CONSTRAINT fk_task_assignments__task_id FOREIGN KEY (task_id)
        REFERENCES workflow.tasks (id) ON DELETE CASCADE,
    CONSTRAINT ck_task_assignments__assignee_given CHECK (num_nonnulls(team_id, user_id) >= 1),
    CONSTRAINT ck_task_assignments__unassigned_after_assigned CHECK (unassigned_at IS NULL OR unassigned_at >= assigned_at),
    CONSTRAINT ck_task_assignments__active_not_unassigned CHECK (NOT is_active OR unassigned_at IS NULL)
);
CREATE UNIQUE INDEX uq_task_assignments__legacy ON workflow.task_assignments (legacy_source, legacy_id, COALESCE(legacy_key, ''))
    WHERE legacy_id IS NOT NULL OR legacy_key IS NOT NULL;
CREATE INDEX ix_task_assignments__task_id ON workflow.task_assignments (task_id);
CREATE INDEX ix_task_assignments__team_id__active ON workflow.task_assignments (team_id) WHERE is_active AND team_id IS NOT NULL;
CREATE INDEX ix_task_assignments__user_id__active ON workflow.task_assignments (user_id) WHERE is_active AND user_id IS NOT NULL;
CREATE INDEX ix_task_assignments__team_id ON workflow.task_assignments (team_id) WHERE team_id IS NOT NULL;
CREATE INDEX ix_task_assignments__user_id ON workflow.task_assignments (user_id) WHERE user_id IS NOT NULL;
CREATE INDEX ix_task_assignments__assigned_by_user_id ON workflow.task_assignments (assigned_by_user_id) WHERE assigned_by_user_id IS NOT NULL;

COMMENT ON TABLE workflow.task_assignments IS 'Who a task is (or was) assigned to: a team, a user, or a user within a team; one row per assignment, kept when reassigned (is_active false, unassigned_at set). Supports several assignees without a schema change, though today a task has one active assignee. Migrated from legacy Tasks.assignedTo / originalAgentID. Child of the task.';
COMMENT ON COLUMN workflow.task_assignments.id IS 'Surrogate key of the assignment; system-generated.';
COMMENT ON COLUMN workflow.task_assignments.tenant_id IS 'Owning tenant (core.tenants); filtered by RLS.';
COMMENT ON COLUMN workflow.task_assignments.task_id IS 'Assigned task (workflow.tasks).';
COMMENT ON COLUMN workflow.task_assignments.team_id IS 'Team the task is assigned to (iam.teams; legacy AuthGroup id in older Tasks rows). NULL = assigned to a user only.';
COMMENT ON COLUMN workflow.task_assignments.user_id IS 'User the task is assigned to (iam.users; legacy WSacounts id). NULL = assigned to a team only.';
COMMENT ON COLUMN workflow.task_assignments.is_active IS 'True = current assignment; false = past assignment (reassigned or task closed).';
COMMENT ON COLUMN workflow.task_assignments.assigned_at IS 'UTC instant the assignment was made.';
COMMENT ON COLUMN workflow.task_assignments.assigned_by_user_id IS 'User who made the assignment (iam.users; legacy Tasks.originalAgentID). NULL = assigned by the system or assigner unknown.';
COMMENT ON COLUMN workflow.task_assignments.unassigned_at IS 'UTC instant the assignment ended; not before assigned_at. NULL = still assigned, or ended when the task closed without a recorded time.';
COMMENT ON COLUMN workflow.task_assignments.legacy_id IS 'Source row id when migrated (Tasks.taskID of the task the assignment came from). NULL = created in threeddx3.';
COMMENT ON COLUMN workflow.task_assignments.legacy_source IS 'Source table when migrated (''Tasks''). NULL = created in threeddx3.';
COMMENT ON COLUMN workflow.task_assignments.legacy_key IS 'Composite source key (e.g. ''<taskID>|assignedTo'') when one id is not enough. NULL = not needed.';
COMMENT ON COLUMN workflow.task_assignments.created_at IS 'UTC instant the row was created; system-generated. [AUDIT]';
COMMENT ON CONSTRAINT pk_task_assignments ON workflow.task_assignments IS 'One row per assignment.';
COMMENT ON CONSTRAINT fk_task_assignments__task_id ON workflow.task_assignments IS 'Assignments are part of their task and go with it.';
COMMENT ON CONSTRAINT ck_task_assignments__assignee_given ON workflow.task_assignments IS 'An assignment names a team, a user, or both.';
COMMENT ON CONSTRAINT ck_task_assignments__unassigned_after_assigned ON workflow.task_assignments IS 'An assignment cannot end before it started.';
COMMENT ON CONSTRAINT ck_task_assignments__active_not_unassigned ON workflow.task_assignments IS 'An active assignment has no end time.';
COMMENT ON INDEX workflow.uq_task_assignments__legacy IS 'Every migrated assignment is traceable and cannot be loaded twice.';
COMMENT ON INDEX workflow.ix_task_assignments__task_id IS 'Assignment history of a task; covers the FK.';
COMMENT ON INDEX workflow.ix_task_assignments__team_id__active IS 'Team task queue: active assignments of a team.';
COMMENT ON INDEX workflow.ix_task_assignments__user_id__active IS 'My tasks: active assignments of a user.';
COMMENT ON INDEX workflow.ix_task_assignments__team_id IS 'All assignments of a team (history, team deletion check); covers the FK to iam.teams.';
COMMENT ON INDEX workflow.ix_task_assignments__user_id IS 'All assignments of a user (history, user deletion check); covers the FK to iam.users.';
COMMENT ON INDEX workflow.ix_task_assignments__assigned_by_user_id IS 'Assignments made by a user; covers the FK to iam.users.';

-- ---------------------------------------------------------------- task_comments
CREATE TABLE workflow.task_comments (
    id                 bigint GENERATED BY DEFAULT AS IDENTITY,
    tenant_id          bigint       NOT NULL DEFAULT core.fn_current_tenant(),
    task_id            bigint       NOT NULL,
    body               text         NOT NULL,
    author_kind        core.actor_kind NOT NULL DEFAULT 'user',
    author_user_id     bigint,
    created_at         timestamptz  NOT NULL DEFAULT now(),
    legacy_id          bigint,
    legacy_source      varchar(64),
    legacy_key         varchar(200),
    CONSTRAINT pk_task_comments PRIMARY KEY (id),
    CONSTRAINT fk_task_comments__task_id FOREIGN KEY (task_id)
        REFERENCES workflow.tasks (id) ON DELETE CASCADE,
    CONSTRAINT ck_task_comments__body_not_blank CHECK (btrim(body) <> '')
);
CREATE UNIQUE INDEX uq_task_comments__legacy ON workflow.task_comments (legacy_source, legacy_id, COALESCE(legacy_key, ''))
    WHERE legacy_id IS NOT NULL OR legacy_key IS NOT NULL;
CREATE INDEX ix_task_comments__task_id__created_at ON workflow.task_comments (task_id, created_at);
CREATE INDEX ix_task_comments__author_user_id ON workflow.task_comments (author_user_id) WHERE author_user_id IS NOT NULL;

COMMENT ON TABLE workflow.task_comments IS 'Notes written on a task (legacy TaskHistory rows of type ''note''), one row per note, in time order. Free text that may name a patient. Child of the task.';
COMMENT ON COLUMN workflow.task_comments.id IS 'Surrogate key of the comment; system-generated.';
COMMENT ON COLUMN workflow.task_comments.tenant_id IS 'Owning tenant (core.tenants); filtered by RLS.';
COMMENT ON COLUMN workflow.task_comments.task_id IS 'Task the comment belongs to (workflow.tasks).';
COMMENT ON COLUMN workflow.task_comments.body IS 'Comment text (legacy TaskHistory.comment); user input, not blank; may name a patient. [PHI-RISK]';
COMMENT ON COLUMN workflow.task_comments.author_kind IS 'Who wrote it (core.actor_kind): ''user'', ''system'' (automatic note), ''integration'' or ''anonymous''.';
COMMENT ON COLUMN workflow.task_comments.author_user_id IS 'User who wrote the comment (iam.users; legacy TaskHistory.createdBy). NULL = system note, or author deleted / unknown.';
COMMENT ON COLUMN workflow.task_comments.created_at IS 'UTC instant the comment was written (legacy TaskHistory.createdAt). [AUDIT]';
COMMENT ON COLUMN workflow.task_comments.legacy_id IS 'Source row id (TaskHistory.ID). NULL = created in threeddx3.';
COMMENT ON COLUMN workflow.task_comments.legacy_source IS 'Source table (''TaskHistory''). NULL = created in threeddx3.';
COMMENT ON COLUMN workflow.task_comments.legacy_key IS 'Composite source key when one id is not enough. NULL = legacy_id is sufficient or not migrated.';
COMMENT ON CONSTRAINT pk_task_comments ON workflow.task_comments IS 'One row per comment.';
COMMENT ON CONSTRAINT fk_task_comments__task_id ON workflow.task_comments IS 'Comments are part of their task and go with it.';
COMMENT ON CONSTRAINT ck_task_comments__body_not_blank ON workflow.task_comments IS 'A comment has visible text.';
COMMENT ON INDEX workflow.uq_task_comments__legacy IS 'Every migrated comment is traceable and cannot be loaded twice.';
COMMENT ON INDEX workflow.ix_task_comments__task_id__created_at IS 'Comments of a task in time order; covers the FK.';
COMMENT ON INDEX workflow.ix_task_comments__author_user_id IS 'Comments by a user; covers the FK to iam.users.';

-- ---------------------------------------------------------------- task_status_history
CREATE TABLE workflow.task_status_history (
    id                 bigint GENERATED BY DEFAULT AS IDENTITY,
    tenant_id          bigint       NOT NULL DEFAULT core.fn_current_tenant(),
    task_id            bigint       NOT NULL,
    from_state         workflow.task_state,
    to_state           workflow.task_state NOT NULL,
    comment            text,
    actor_kind         core.actor_kind NOT NULL DEFAULT 'user',
    actor_user_id      bigint,
    actor_role_id      bigint,
    changed_at         timestamptz  NOT NULL DEFAULT now(),
    legacy_id          bigint,
    legacy_source      varchar(64),
    legacy_key         varchar(200),
    CONSTRAINT pk_task_status_history PRIMARY KEY (id),
    CONSTRAINT fk_task_status_history__task_id FOREIGN KEY (task_id)
        REFERENCES workflow.tasks (id) ON DELETE RESTRICT,
    CONSTRAINT ck_task_status_history__state_changed CHECK (from_state IS DISTINCT FROM to_state)
);
CREATE UNIQUE INDEX uq_task_status_history__legacy ON workflow.task_status_history (legacy_source, legacy_id, COALESCE(legacy_key, ''))
    WHERE legacy_id IS NOT NULL OR legacy_key IS NOT NULL;
CREATE INDEX ix_task_status_history__task_id__changed_at ON workflow.task_status_history (task_id, changed_at);

COMMENT ON TABLE workflow.task_status_history IS 'Every state change of a task: from, to, who (user and acting role), when, with an optional note. Migrated tasks get one row for their creation state. Append-only (trg_task_status_history__append_only); a task with history cannot be deleted.';
COMMENT ON COLUMN workflow.task_status_history.id IS 'Surrogate key of the history row; system-generated.';
COMMENT ON COLUMN workflow.task_status_history.tenant_id IS 'Owning tenant (core.tenants); filtered by RLS.';
COMMENT ON COLUMN workflow.task_status_history.task_id IS 'Task whose state changed (workflow.tasks).';
COMMENT ON COLUMN workflow.task_status_history.from_state IS 'State before the change (workflow.task_state). NULL = the task''s first state (creation).';
COMMENT ON COLUMN workflow.task_status_history.to_state IS 'State after the change: ''open'', ''in_progress'', ''blocked'', ''done'' or ''cancelled'' (meanings as tasks.state).';
COMMENT ON COLUMN workflow.task_status_history.comment IS 'Note entered with the change; free text that may name a patient. NULL = no note. [PHI-RISK]';
COMMENT ON COLUMN workflow.task_status_history.actor_kind IS 'Who made the change (core.actor_kind): ''user'', ''system'', ''integration'' or ''anonymous''.';
COMMENT ON COLUMN workflow.task_status_history.actor_user_id IS 'User who made the change (iam.users id). No FK by design: append-only history must survive user deletion and cannot be SET NULL. NULL = not a user action.';
COMMENT ON COLUMN workflow.task_status_history.actor_role_id IS 'Role the user acted in (iam.roles id, from core.fn_current_role_id()). No FK by design, same reason as actor_user_id. NULL = not a user action, or role not recorded (migrated rows).';
COMMENT ON COLUMN workflow.task_status_history.changed_at IS 'UTC instant of the change. [AUDIT]';
COMMENT ON COLUMN workflow.task_status_history.legacy_id IS 'Source row id when migrated. NULL = created in threeddx3 or derived from the task row.';
COMMENT ON COLUMN workflow.task_status_history.legacy_source IS 'Source table when migrated (''Tasks'' for the derived creation row). NULL = created in threeddx3.';
COMMENT ON COLUMN workflow.task_status_history.legacy_key IS 'Composite source key (e.g. ''<taskID>|created'') when one id is not enough. NULL = not needed.';
COMMENT ON CONSTRAINT pk_task_status_history ON workflow.task_status_history IS 'One row per task state change.';
COMMENT ON CONSTRAINT fk_task_status_history__task_id ON workflow.task_status_history IS 'A task with state history cannot be deleted (history; append-only rows cannot cascade).';
COMMENT ON CONSTRAINT ck_task_status_history__state_changed ON workflow.task_status_history IS 'A history row records an actual change of state.';
COMMENT ON INDEX workflow.uq_task_status_history__legacy IS 'Every migrated history row is traceable and cannot be loaded twice.';
COMMENT ON INDEX workflow.ix_task_status_history__task_id__changed_at IS 'State timeline of a task; covers the FK.';
CREATE TRIGGER trg_task_status_history__append_only BEFORE UPDATE OR DELETE ON workflow.task_status_history
    FOR EACH ROW EXECUTE FUNCTION core.fn_reject_mutation();
COMMENT ON TRIGGER trg_task_status_history__append_only ON workflow.task_status_history IS 'Task status history is append-only: UPDATE and DELETE are rejected.';

-- ---------------------------------------------------------------- task_due_date_changes
CREATE TABLE workflow.task_due_date_changes (
    id                 bigint GENERATED BY DEFAULT AS IDENTITY,
    tenant_id          bigint       NOT NULL DEFAULT core.fn_current_tenant(),
    task_id            bigint       NOT NULL,
    old_due_at         timestamptz,
    new_due_at         timestamptz,
    reason_id          bigint       NOT NULL,
    reason_note        text,
    actor_kind         core.actor_kind NOT NULL DEFAULT 'user',
    actor_user_id      bigint,
    actor_role_id      bigint,
    changed_at         timestamptz  NOT NULL DEFAULT now(),
    legacy_id          bigint,
    legacy_source      varchar(64),
    legacy_key         varchar(200),
    CONSTRAINT pk_task_due_date_changes PRIMARY KEY (id),
    CONSTRAINT fk_task_due_date_changes__task_id FOREIGN KEY (task_id)
        REFERENCES workflow.tasks (id) ON DELETE RESTRICT,
    CONSTRAINT ck_task_due_date_changes__changed CHECK (old_due_at IS DISTINCT FROM new_due_at)
);
CREATE UNIQUE INDEX uq_task_due_date_changes__legacy ON workflow.task_due_date_changes (legacy_source, legacy_id, COALESCE(legacy_key, ''))
    WHERE legacy_id IS NOT NULL OR legacy_key IS NOT NULL;
CREATE INDEX ix_task_due_date_changes__task_id__changed_at ON workflow.task_due_date_changes (task_id, changed_at);
CREATE INDEX ix_task_due_date_changes__reason_id ON workflow.task_due_date_changes (reason_id);

COMMENT ON TABLE workflow.task_due_date_changes IS 'Every change of a task''s due date with its mandatory reason (D4 rule 9; CS screens use ReasonsForChangeDueDateCSTasks: 4 reasons with default day offsets). Migrated from legacy TaskHistory rows of type ''duedatechange''. Feeds SLA and "how often are deadlines moved and why" reporting. Append-only (trg_task_due_date_changes__append_only).';
COMMENT ON COLUMN workflow.task_due_date_changes.id IS 'Surrogate key of the change; system-generated.';
COMMENT ON COLUMN workflow.task_due_date_changes.tenant_id IS 'Owning tenant (core.tenants); filtered by RLS.';
COMMENT ON COLUMN workflow.task_due_date_changes.task_id IS 'Task whose due date changed (workflow.tasks).';
COMMENT ON COLUMN workflow.task_due_date_changes.old_due_at IS 'Due time before the change, UTC instant (legacy TaskHistory.oldDueDate, a date, converted the same way stage 60 converts tasks.due_at). NULL = the task had no due date before.';
COMMENT ON COLUMN workflow.task_due_date_changes.new_due_at IS 'Due time after the change, UTC instant (legacy TaskHistory.newDueDate, converted likewise). NULL = the due date was removed (e.g. task marked Rush).';
COMMENT ON COLUMN workflow.task_due_date_changes.reason_id IS 'Why the date moved: a core.lookup_values row of lookup type ''cs_due_date_change_reason'' (seeded from ReasonsForChangeDueDateCSTasks.json; migrated rows without a reason get the seeded ''legacy_unspecified'' value). Required.';
COMMENT ON COLUMN workflow.task_due_date_changes.reason_note IS 'Free-text explanation added to the reason (legacy TaskHistory.comment); may name a patient. NULL = no note. [PHI-RISK]';
COMMENT ON COLUMN workflow.task_due_date_changes.actor_kind IS 'Who changed the date (core.actor_kind): ''user'', ''system'' (e.g. automatic re-plan), ''integration'' or ''anonymous''.';
COMMENT ON COLUMN workflow.task_due_date_changes.actor_user_id IS 'User who changed the date (iam.users id; legacy TaskHistory.createdBy). No FK by design: append-only history must survive user deletion. NULL = not a user action or unknown.';
COMMENT ON COLUMN workflow.task_due_date_changes.actor_role_id IS 'Role the user acted in (iam.roles id). No FK by design, same reason as actor_user_id. NULL = not a user action, or role not recorded (migrated rows).';
COMMENT ON COLUMN workflow.task_due_date_changes.changed_at IS 'UTC instant of the change (legacy TaskHistory.createdAt). [AUDIT]';
COMMENT ON COLUMN workflow.task_due_date_changes.legacy_id IS 'Source row id (TaskHistory.ID). NULL = created in threeddx3.';
COMMENT ON COLUMN workflow.task_due_date_changes.legacy_source IS 'Source table (''TaskHistory''). NULL = created in threeddx3.';
COMMENT ON COLUMN workflow.task_due_date_changes.legacy_key IS 'Composite source key when one id is not enough. NULL = legacy_id is sufficient or not migrated.';
COMMENT ON CONSTRAINT pk_task_due_date_changes ON workflow.task_due_date_changes IS 'One row per due-date change.';
COMMENT ON CONSTRAINT fk_task_due_date_changes__task_id ON workflow.task_due_date_changes IS 'A task with due-date history cannot be deleted (history; append-only rows cannot cascade).';
COMMENT ON CONSTRAINT ck_task_due_date_changes__changed ON workflow.task_due_date_changes IS 'A change row records an actual change: old and new due dates differ.';
COMMENT ON INDEX workflow.uq_task_due_date_changes__legacy IS 'Every migrated change is traceable to TaskHistory.ID and cannot be loaded twice.';
COMMENT ON INDEX workflow.ix_task_due_date_changes__task_id__changed_at IS 'Due-date timeline of a task; covers the FK.';
COMMENT ON INDEX workflow.ix_task_due_date_changes__reason_id IS 'Reports by reason ("why are deadlines moved"); covers the FK to core.lookup_values.';
CREATE TRIGGER trg_task_due_date_changes__append_only BEFORE UPDATE OR DELETE ON workflow.task_due_date_changes
    FOR EACH ROW EXECUTE FUNCTION core.fn_reject_mutation();
COMMENT ON TRIGGER trg_task_due_date_changes__append_only ON workflow.task_due_date_changes IS 'Due-date history is append-only: UPDATE and DELETE are rejected.';

-- ---------------------------------------------------------------- task_relations
CREATE TABLE workflow.task_relations (
    id                 bigint GENERATED BY DEFAULT AS IDENTITY,
    tenant_id          bigint       NOT NULL DEFAULT core.fn_current_tenant(),
    parent_task_id     bigint       NOT NULL,
    child_task_id      bigint       NOT NULL,
    relation_type      varchar(20)  NOT NULL,
    created_at         timestamptz  NOT NULL DEFAULT now(),
    created_by_user_id bigint,
    CONSTRAINT pk_task_relations PRIMARY KEY (id),
    CONSTRAINT uq_task_relations__parent__child__type UNIQUE (parent_task_id, child_task_id, relation_type),
    CONSTRAINT fk_task_relations__parent_task_id FOREIGN KEY (parent_task_id)
        REFERENCES workflow.tasks (id) ON DELETE CASCADE,
    CONSTRAINT fk_task_relations__child_task_id FOREIGN KEY (child_task_id)
        REFERENCES workflow.tasks (id) ON DELETE CASCADE,
    CONSTRAINT ck_task_relations__not_self CHECK (parent_task_id <> child_task_id),
    CONSTRAINT ck_task_relations__relation_type CHECK (relation_type IN ('blocks', 'depends_on', 'duplicates', 'relates_to'))
);
CREATE INDEX ix_task_relations__child_task_id ON workflow.task_relations (child_task_id);

COMMENT ON TABLE workflow.task_relations IS 'Link table between two tasks: one blocks, depends on, duplicates or relates to the other. One row per pair and relation type; removed with either task.';
COMMENT ON COLUMN workflow.task_relations.id IS 'Surrogate key of the relation; system-generated.';
COMMENT ON COLUMN workflow.task_relations.tenant_id IS 'Owning tenant (core.tenants); filtered by RLS.';
COMMENT ON COLUMN workflow.task_relations.parent_task_id IS 'Task on the left of the relation (the blocker, the dependent, the duplicate or the related task).';
COMMENT ON COLUMN workflow.task_relations.child_task_id IS 'Task on the right of the relation; never the same task as parent_task_id.';
COMMENT ON COLUMN workflow.task_relations.relation_type IS 'Meaning of the link: ''blocks'' = parent must finish before child can; ''depends_on'' = parent needs child finished first; ''duplicates'' = parent is a duplicate of child; ''relates_to'' = informational link.';
COMMENT ON COLUMN workflow.task_relations.created_at IS 'UTC instant the link was made; system-generated. [AUDIT]';
COMMENT ON COLUMN workflow.task_relations.created_by_user_id IS 'User who made the link; no FK by design. NULL = system. [AUDIT]';
COMMENT ON CONSTRAINT pk_task_relations ON workflow.task_relations IS 'One row per relation.';
COMMENT ON CONSTRAINT uq_task_relations__parent__child__type ON workflow.task_relations IS 'The same relation between the same two tasks is recorded once; also covers the parent FK.';
COMMENT ON CONSTRAINT fk_task_relations__parent_task_id ON workflow.task_relations IS 'A link row goes with either of its tasks.';
COMMENT ON CONSTRAINT fk_task_relations__child_task_id ON workflow.task_relations IS 'A link row goes with either of its tasks.';
COMMENT ON CONSTRAINT ck_task_relations__not_self ON workflow.task_relations IS 'A task cannot be related to itself.';
COMMENT ON CONSTRAINT ck_task_relations__relation_type ON workflow.task_relations IS 'Only the four documented relation types are allowed.';
COMMENT ON INDEX workflow.ix_task_relations__child_task_id IS 'Relations pointing at a task; covers the child FK.';
